"""

@dataclass
class Declaration:
    prop: str
    value: str
    important: bool = False
    raw: str = ""
    removed: bool = False

@dataclass
class Rule:
    selector: str
    items: List[Any] = field(default_factory=list)
    keep_empty: bool = False
    original_selector: str = ""

@dataclass
class AtRule:
    name: str
    prelude: str
    items: Optional[List[Any]] = None
    block_type: str = "rules"  # rules, decls, mixed

@dataclass
class Comment:
    text: str

# ---------------- CLI ----------------
@dataclass
class Options:
    minify: bool = False
    output_file: Optional[str] = None
    output_dir: Optional[str] = None
    sourcemap: bool = False
    bundle: bool = False
    browserslist: bool = False
    targets: Optional[str] = None
    custom_media: bool = False
    error_recovery: bool = False
    css_modules: bool = False
    css_modules_file: Optional[str] = None
    css_modules_pattern: str = "[hash]_[local]"
    css_modules_dashed: bool = False

class ArgError(Exception):
    def __init__(self, msg, code=2):
        super().__init__(msg); self.code=code

def parse_args(argv: List[str]) -> Tuple[Options, List[str]]:
    opts = Options()
    inputs: List[str] = []
    i = 0
    end = False
    while i < len(argv):
        a = argv[i]
        if end:
            inputs.append(a); i += 1; continue
        if a == "--":
            end = True; i += 1; continue
        if a in ("-h", "--help"):
            print(HELP, end="")
            sys.exit(0)
        if a in ("-V", "--version"):
            print(VERSION)
            sys.exit(0)
        if a in ("-m", "--minify"):
            opts.minify = True; i += 1; continue
        if a == "--sourcemap": opts.sourcemap = True; i += 1; continue
        if a == "--bundle": opts.bundle = True; i += 1; continue
        if a == "--browserslist": opts.browserslist = True; i += 1; continue
        if a == "--custom-media": opts.custom_media = True; i += 1; continue
        if a == "--error-recovery": opts.error_recovery = True; i += 1; continue
        if a == "--css-modules-dashed-idents": opts.css_modules_dashed = True; i += 1; continue
        if a in ("-o", "--output-file") or a.startswith("--output-file="):
            if a.startswith("--output-file="):
                opts.output_file = a.split("=",1)[1]
            else:
                if i+1 >= len(argv): raise ArgError("error: The argument '--output-file <OUTPUT_FILE>' requires a value but none was supplied\n\nFor more information try --help\n")
                opts.output_file = argv[i+1]; i += 1
            i += 1; continue
        if a in ("-d", "--output-dir") or a.startswith("--output-dir="):
            if a.startswith("--output-dir="):
                opts.output_dir = a.split("=",1)[1]
            else:
                if i+1 >= len(argv): raise ArgError("error: The argument '--output-dir <OUTPUT_DIR>' requires a value but none was supplied\n\nFor more information try --help\n")
                opts.output_dir = argv[i+1]; i += 1
            i += 1; continue
        if a in ("-t", "--targets") or a.startswith("--targets="):
            if a.startswith("--targets="):
                val = a.split("=",1)[1]
            else:
                if i+1 >= len(argv): raise ArgError("error: The argument '--targets <TARGETS>' requires a value but none was supplied\n\nFor more information try --help\n")
                val = argv[i+1]; i += 1
            opts.targets = val; i += 1; continue
        if a == "--css-modules-pattern" or a.startswith("--css-modules-pattern="):
            if a.startswith("--css-modules-pattern="):
                opts.css_modules_pattern = a.split("=",1)[1]
            else:
                if i+1 >= len(argv): raise ArgError("error: The argument '--css-modules-pattern <CSS_MODULES_PATTERN>' requires a value but none was supplied\n\nFor more information try --help\n")
                opts.css_modules_pattern = argv[i+1]; i += 1
            i += 1; continue
        if a == "--css-modules" or a.startswith("--css-modules="):
            opts.css_modules = True
            if a.startswith("--css-modules="):
                opts.css_modules_file = a.split("=",1)[1]
                i += 1; continue
            # clap optional value: greedily consume next non-option token.
            if i+1 < len(argv) and not argv[i+1].startswith("-"):
                opts.css_modules_file = argv[i+1]
                i += 2
            else:
                i += 1
            continue
        if a.startswith("--"):
